const D = { energy: .6, scale: 1, speed: 1, density: .5, tri: .45, hue: 196, x: .5, y: .5, style: 'false_colour', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Tokamak — the poloidal cross-section --------------------------------------------------
// Slice the torus and look down the tube. The plasma current and the shaping coils are rings,
// so in this plane they are just wires, and the poloidal flux is the log potential they make:
//   psi(x,z) = -SUM_k I_k ln|r - r_k|
// Everything else falls out of that instead of being drawn. Put a coil UNDER the plasma
// carrying current the same way and the two fields cancel somewhere between them: a null, the
// X-POINT. The contour through it is the SEPARATRIX, the last closed surface — inside it the
// field lines close on themselves and confine, outside they are open and sweep to the divertor
// plates. The X-point's location is exactly z = -zc·Ip/(Ip+Ic), which is why moving the coil
// current moves the strike point, and it does that here too.
// Nested surfaces are labelled by the safety factor q. Where q is RATIONAL the surface is
// resonant with a helical perturbation and tears open into a chain of m magnetic ISLANDS —
// the 2/1 and 3/2 chains here, rotating with the plasma at their own incommensurate rates.
// And the core is unstable: q dips below 1, the temperature peaks, the q=1 surface reconnects
// and dumps the core heat outward as a pulse — a SAWTOOTH — then peaks again, forever.
// -------------------------------------------------------------------------------------------

const TAU = 6.283185307;
const style = P.style;
const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };
const fr2 = (i, j) => { const s = Math.sin(i * 127.1 + j * 311.7 + sd * 74.77) * 43758.5453; return s - Math.floor(s); };

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dtr = K.t - S.lastT; S.lastT = K.t;
dtr = dtr < 0 ? 0 : (dtr > 0.06 ? 0.06 : dtr);
if (S.T == null) S.T = 0;
S.T += dtr * (0.25 + P.speed * 0.9);
const ts = S.T;

const en = Math.min(1, Math.max(0, P.energy));
const scl = Math.max(0.4, P.scale);
const dens = Math.min(1, Math.max(0, P.density));
const tri = Math.min(1, Math.max(0, P.tri));

// incommensurate real-time floor
const dr1 = Math.sin(K.t * 0.061) * 0.9 + Math.sin(K.t * 0.143 + 1.7) * 0.5 + Math.sin(K.t * 0.229) * 0.32;
const dr2 = Math.sin(K.t * 0.077 + 2.1) * 0.8 + Math.sin(K.t * 0.181 + 0.4) * 0.44;

const h2rgb = (h, s, v) => {
  h = (((h % 360) + 360) % 360) / 60;
  const c = v * s, x = c * (1 - Math.abs(h % 2 - 1)), m = v - c;
  if (h < 1) return [c + m, x + m, m];
  if (h < 2) return [x + m, c + m, m];
  if (h < 3) return [m, c + m, x + m];
  if (h < 4) return [m, x + m, c + m];
  if (h < 5) return [x + m, m, c + m];
  return [c + m, m, x + m];
};

const BW = 152, BH = Math.max(56, Math.round(BW * height / width));
if (!S.g || S.key !== width + 'x' + height) {
  S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.key = width + 'x' + height;
  S.GN = new Float32Array(BW * BH); S.gnKey = null;
}
const g = S.g;
if (S.gnKey !== S.key + ':' + sd) { S.gnKey = S.key + ':' + sd; for (let j = 0; j < BH; j++) for (let i = 0; i < BW; i++) S.GN[j * BW + i] = fr2(i * 2.7 + 1.3, j * 5.1 + 7.9); }
const GN = S.GN;

const L = BW / BH;
const cxF = Math.min(1, Math.max(0, P.x)) * L, cyF = Math.min(1, Math.max(0, P.y));

// ---- the coil set (x outward, z up), in field units ----------------------------------------
// The Shafranov shift is real: the hotter the plasma, the further out the magnetic axis sits.
const sh = (0.02 + en * 0.055) * scl * (1 + 0.10 * dr1);
const zc = 0.52 * scl * (1 + 0.05 * dr2);
const txo = -0.13 * scl * tri;                      // coils pulled inboard -> positive triangularity
const Ic = 0.34 + 0.22 * (0.5 + 0.5 * Math.sin(ts * 0.043));   // divertor current breathes -> the
const Iu = 0.22 + 0.10 * (0.5 + 0.5 * Math.sin(ts * 0.067));   // strike point walks, as it really does
const ap = 0.27 * scl;                              // the plasma current is DISTRIBUTED, not a point
const WX = [sh, txo, txo, -0.72 * scl, 0.78 * scl];
const WZ = [0, -zc, zc * 1.26, 0.06, -0.04];
const WI = [1, Ic, Iu, -0.10, -0.14];
const WA = [ap * ap, 0.0016 * scl * scl, 0.0016 * scl * scl, 0.004 * scl * scl, 0.004 * scl * scl];
const NW = 5;
// Exact 2D flux of a UNIFORM current channel of radius a: log outside, parabolic inside.
// A point filament would make psi diverge at the axis and crush the whole plasma to a dot —
// the parabolic core is what gives a real machine its broad, gently-peaked profile.
const psiAt = (x, z) => {
  let s = 0;
  for (let k = 0; k < NW; k++) {
    const dx = x - WX[k], dz = z - WZ[k], r2 = dx * dx + dz * dz, a2 = WA[k];
    s -= r2 > a2 ? WI[k] * 0.5 * Math.log(r2) : WI[k] * (0.5 * Math.log(a2) + (r2 - a2) / (2 * a2));
  }
  return s;
};
// the X-point is the saddle on the line joining plasma and divertor coil: scan for the minimum
const findX = (kc) => {
  let lo = 1e9, lz = 0, lx = 0;
  for (let s2 = 1; s2 < 40; s2++) {
    const u = s2 / 40;
    const x = WX[0] + (WX[kc] - WX[0]) * u, z = WZ[0] + (WZ[kc] - WZ[0]) * u;
    const v = psiAt(x, z);
    if (v < lo) { lo = v; lz = z; lx = x; }
  }
  return [lo, lx, lz];
};
const XL = findX(1), XU = findX(2);
const prim = XL[0] >= XU[0] ? XL : XU;               // the primary separatrix is the inner null
const psiX = prim[0];
const psiA = psiAt(WX[0], WZ[0]);
const dpsi = Math.max(1e-4, psiA - psiX);

// ---- sawtooth: peak, crash, peak. slow and partial on purpose — never a flash ---------------
const Tsaw = 13.5 / (0.5 + en * 0.9);
const sawPh = ((ts / Tsaw) % 1 + 1) % 1;
const peakAmt = sawPh < 0.90 ? sawPh / 0.90 : 1 - (sawPh - 0.90) / 0.10;
const hp = sawPh > 0.90 ? (sawPh - 0.90) / 0.10 : -1;   // the heat pulse running outward after a crash

// ---- island chains at the rational surfaces ------------------------------------------------
const nIsl = dens > 0.66 ? 3 : (dens > 0.28 ? 2 : 1);
const IM = [2, 3, 5], IR = [0.52, 0.26, 0.74], IW = [0.16, 0.12, 0.09];
const IA = [0.055, 0.038, 0.022];
const IO = [0.23, -0.31, 0.17];                       // each chain rotates at its own rate

const Nc = Math.round(6 + dens * 12);                 // flux surfaces drawn

let bg0, cLo, cMi, cHi, cLine, cSol, metal;
if (style === 'photograph') { bg0 = [0.030, 0.026, 0.038]; cLo = h2rgb(292, 0.80, 0.30); cMi = h2rgb(300, 0.62, 0.56); cHi = h2rgb(316, 0.20, 0.90); cLine = h2rgb(300, 0.35, 0.85); cSol = h2rgb(286, 0.86, 0.62); metal = [0.44, 0.42, 0.47]; }
else if (style === 'contour_map') { bg0 = [0.035, 0.048, 0.072]; cLo = h2rgb(190, 0.70, 0.5); cMi = h2rgb(190, 0.55, 0.8); cHi = h2rgb(188, 0.20, 1.0); cLine = h2rgb(190, 0.70, 1.0); cSol = h2rgb(38, 0.80, 0.95); metal = [0.14, 0.19, 0.28]; }
else if (style === 'ironbow') { bg0 = [0.02, 0.02, 0.09]; cLo = h2rgb(258, 0.85, 0.36); cMi = h2rgb(330, 0.80, 0.76); cHi = [1.0, 0.96, 0.70]; cLine = [1, 1, 0.9]; cSol = h2rgb(212, 0.70, 0.66); metal = [0.30, 0.30, 0.38]; }
else if (style === 'bolometer') { bg0 = [0.045, 0.045, 0.048]; cLo = [0.20, 0.20, 0.21]; cMi = [0.52, 0.52, 0.52]; cHi = [0.96, 0.96, 0.95]; cLine = [0.99, 0.99, 0.98]; cSol = [0.66, 0.66, 0.67]; metal = [0.34, 0.34, 0.35]; }
else { bg0 = [0.026, 0.034, 0.048]; cLo = h2rgb(P.hue + 44, 0.90, 0.30); cMi = h2rgb(P.hue - 26, 0.82, 0.74); cHi = h2rgb(P.hue - 60, 0.14, 1.0); cLine = h2rgb(P.hue, 0.42, 1.0); cSol = h2rgb(P.hue + 26, 0.80, 0.68); metal = [0.40, 0.44, 0.50]; }

// plasma emission ramp — black at zero, so the metal underneath shows through
const ramp = (v, ins) => {
  const c1 = ins ? cLo : cSol, c2 = ins ? cMi : cSol, c3 = ins ? cHi : cHi;
  if (v < 0.30) { const u = v / 0.30; return [c1[0] * u, c1[1] * u, c1[2] * u]; }
  if (v < 0.68) { const u = (v - 0.30) / 0.38; return [c1[0] + (c2[0] - c1[0]) * u, c1[1] + (c2[1] - c1[1]) * u, c1[2] + (c2[2] - c1[2]) * u]; }
  const u = (v - 0.68) / 0.32; return [c2[0] + (c3[0] - c2[0]) * u, c2[1] + (c3[1] - c2[1]) * u, c2[2] + (c3[2] - c2[2]) * u];
};
const aVx = 0.50 * scl, aVz = 0.44 * scl;

g.loadPixels();
const gp = g.pixels;
const lineW = style === 'contour_map' ? 0.30 : 0.22;
const fillK = style === 'contour_map' ? 0.10 : 1.0;

for (let j = 0; j < BH; j++) {
  const z = -((j + 0.5) / BH - cyF);
  for (let i = 0; i < BW; i++) {
    const x = (i + 0.5) / BH - cxF;
    const p = j * BW + i;

    let psin = (psiAt(x, z) - psiX) / dpsi;
    const th = Math.atan2(z - WZ[0], x - WX[0]);

    // tear the resonant surfaces open into island chains
    for (let q = 0; q < nIsl; q++) {
      const d = (psin - IR[q]) / IW[q];
      if (d > -3.2 && d < 3.2) psin += IA[q] * (0.4 + en) * Math.exp(-d * d) * Math.cos(IM[q] * th - ts * IO[q] * (1 + en * 0.7));
    }

    const inside = psin > 0;
    const pc = psin < 0 ? 0 : (psin > 1 ? 1 : psin);

    // temperature: peaked profile, and the core runs its sawtooth
    let T = Math.pow(pc, 1.05 - en * 0.35);
    T *= 1 + peakAmt * (0.30 + en * 0.42) * Math.exp(-Math.pow((1 - pc) / 0.30, 2));
    if (hp >= 0) {                                     // the crash dumps a ring of heat outward
      const rr = (pc - (0.88 - hp * 0.82)) / 0.11;
      T += 0.30 * (1 - hp) * Math.exp(-rr * rr) * (0.4 + en);
    }
    T *= 0.40 + en * 0.50;

    // flux surfaces, evenly spaced in sqrt(psi) the way a real contour plot draws them
    const rho = Math.sqrt(pc);
    let band = Math.abs(((rho * Nc) % 1) - 0.5) * 2;    // 1 on a contour
    band = Math.pow(Math.max(0, band - (1 - lineW)) / lineW, 1.4);

    // outside the separatrix: the scrape-off layer, open field lines streaming to the strikes
    let sol = 0, solB = 0;
    if (!inside) {
      const dd = -psin;
      sol = Math.exp(-dd * (2.4 + (1 - en) * 2.6));
      const fl = 0.5 + 0.5 * Math.sin(th * 2.0 - ts * (1.1 + en * 1.5) + dd * 9);
      solB = sol * (0.30 + 0.70 * fl);
      let sb = Math.abs((((dd * 14) % 1)) - 0.5) * 2;
      sb = Math.pow(Math.max(0, sb - 0.72) / 0.28, 1.3);
      solB += sol * sb * 0.55;
    }

    // the X-point itself glows: that is where the current sheet is
    const dxx = x - prim[1], dzz = z - prim[2];
    const xg = Math.exp(-(dxx * dxx + dzz * dzz) / (0.0055 * scl * scl)) * (0.13 + en * 0.17);

    // ---- the machine around it: lit vessel interior, then a ring of segmented blanket ----
    const rvx = (x - sh) / aVx, rvz = z / aVz;
    const rv = Math.sqrt(rvx * rvx + rvz * rvz);
    const va = Math.atan2(rvz, rvx);
    let mach;
    if (rv < 1) {
      mach = 0.215 + 0.080 * (1 - rv) + 0.038 * Math.cos(va * 3 + 0.6);       // metal, catching the glow
    } else if (rv < 1.34) {
      const q2 = (rv - 1) / 0.34;
      const seg = Math.abs(((va / TAU * 26 + 0.5) % 1) - 0.5) * 2;            // blanket modules, tile by tile
      const gap = seg > 0.86 ? 0 : 1;
      mach = (0.325 - q2 * 0.110) * gap * (0.62 + 0.38 * Math.cos(va + 0.9))  // raking light around the ring
           + 0.070 + 0.040 * Math.cos(va * 7);
    } else {
      const q2 = Math.min(1, (rv - 1.34) / 0.55);
      mach = 0.150 * (1 - q2 * 0.42) + 0.040 * Math.cos(va * 16 + rv * 5) + 0.030 * Math.cos(va * 4 - 1.1);    // structure falling away behind
    }
    mach *= style === 'contour_map' ? 0.42 : 1;
    // the plasma lights the metal it sits in
    mach += Math.exp(-Math.max(0, rv - 0.15) * 1.9) * T * (0.20 + en * 0.18);

    // ---- the metal is neutral and lit; the plasma is emission laid over it -----------------
    mach += (GN[p] - 0.5) * 0.045;
    const mv = Math.min(1, Math.max(0, mach * 1.55));
    let R = bg0[0] + (metal[0] - bg0[0]) * mv, G2 = bg0[1] + (metal[1] - bg0[1]) * mv, B = bg0[2] + (metal[2] - bg0[2]) * mv;

    let pv = T * fillK * 0.92 + band * (inside ? 0.55 : 0.0) * (0.35 + T * 0.9)
           + solB * (0.44 + en * 0.42) + xg;
    if (style === 'contour_map') pv = band * (inside ? 0.95 : 0) + solB * 0.75 + xg + T * 0.10;
    pv = pv < 0 ? 0 : (pv > 1 ? 1 : pv);
    const cc = ramp(pv, inside);
    R += cc[0]; G2 += cc[1]; B += cc[2];
    const v = pv;

    const lift = A.rms * 0.09 + K.swell * 0.03;
    R += lift; G2 += lift * 0.95; B += lift * 0.9;
    const o = 4 * p;
    gp[o] = R < 0 ? 0 : (R > 1 ? 255 : R * 255);
    gp[o + 1] = G2 < 0 ? 0 : (G2 > 1 ? 255 : G2 * 255);
    gp[o + 2] = B < 0 ? 0 : (B > 1 ? 255 : B * 255);
    gp[o + 3] = 255;
  }
}
g.updatePixels();
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// ---- the machine: vessel wall + divertor plates --------------------------------------------
const pxF = f => (f + cxF) * BH / BW * width, pyF = f => (cyF - f) * height;
const aMul = P.alpha / 100;
const css = (c, a) => 'rgba(' + Math.round(Math.min(255, c[0] * 255)) + ',' + Math.round(Math.min(255, c[1] * 255)) + ',' + Math.round(Math.min(255, c[2] * 255)) + ',' + Math.min(1, Math.max(0, a)).toFixed(3) + ')';
push();
noFill();
strokeWeight(Math.max(1.2, 0.004 * Math.min(width, height) * scl));
stroke(0, 0, 100, 40);
drawingContext.strokeStyle = css(style === 'contour_map' ? cLine : [0.62, 0.66, 0.72], 0.42 * aMul);
const dV = 0.42 * tri;
beginShape();
for (let k = 0; k <= 52; k++) {
  const a = k / 52 * TAU;
  const vx = sh + aVx * Math.cos(a + dV * Math.sin(a));
  const vz = aVz * Math.sin(a);
  vertex(pxF(vx), pyF(vz));
}
endShape(CLOSE);
// divertor plates, right where the separatrix legs land
strokeWeight(Math.max(1.6, 0.006 * Math.min(width, height) * scl));
drawingContext.strokeStyle = css([0.72, 0.74, 0.78], 0.50 * aMul);
const zD = prim[2] - 0.10 * scl;
line(pxF(prim[1] - 0.20 * scl), pyF(zD + 0.045 * scl), pxF(prim[1] - 0.03 * scl), pyF(zD - 0.012 * scl));
line(pxF(prim[1] + 0.03 * scl), pyF(zD - 0.012 * scl), pxF(prim[1] + 0.20 * scl), pyF(zD + 0.045 * scl));
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
